mapper.select:
SELECT DISTINCT ON (logger_id) logger_id, measured_at, temperature, humidity, ROUND(battery_pct)::INTEGER AS battery_pct
FROM readings
WHERE gateway_id = #{gatewayId} AND measured_at >= #{startedAt}
AND measured_at <= #{endedAt}
ORDER BY logger_id, measured_at DESC, reading_id DESC

SELECT
measured_at,
temperature,
humidity

FROM readings

WHERE gateway_id = #{gatewayId}
AND logger_id = #{loggerId}
AND measured_at >= #{startedAt}

    AND measured_at <= #{endedAt}


ORDER BY measured_at ASC
